def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 3:
        return 'C'

    # Gather recent behavior compactly
    last_me, last_op = history[-1]

    # Consecutive opponent defections streak
    streak = 0
    for (a, b) in reversed(history):
        if b == 'D':
            streak += 1
        else:
            break

    # Consecutive mutual cooperation streak
    cc_streak = 0
    for (a, b) in reversed(history):
        if a == 'C' and b == 'C':
            cc_streak += 1
        else:
            break

    # Recent window stats
    w = 10 if n >= 10 else n
    recent = history[-w:]
    recent_opp_d = sum(1 for (a, b) in recent if b == 'D')
    recent_opp_c = w - recent_opp_d

    # Overall stats
    opp_c = 0
    my_c = 0
    for (a, b) in history:
        if b == 'C':
            opp_c += 1
        if a == 'C':
            my_c += 1
    opp_d = n - opp_c

    # Endgame: exploit a very cooperative opponent if they've been forgiving
    if n >= 93:
        if opp_c >= n - 3:
            return 'D'
        if opp_c >= int(0.8 * n):
            return 'D' if rng.random() < 0.7 else 'C'
        return 'C'

    # Near endgame light probing
    if n >= 85 and opp_c >= int(0.9 * n):
        return 'D' if rng.random() < 0.3 else 'C'

    # Detect likely always-defector
    if n >= 8 and opp_d >= n - 2:
        return 'D' if rng.random() > 0.05 else 'C'

    # Very cooperative establishment: keep mutual cooperation
    if cc_streak >= 3 and recent_opp_c >= w - 1:
        # Rare mild probe against super-cooperative opponents mid-game
        if n >= 30 and opp_d <= 1 and rng.random() < 0.05:
            return 'D'
        return 'C'

    # Opponent just defected
    if last_op == 'D':
        # If they've defected a lot lately, defect firmly
        if recent_opp_d >= 5:
            return 'D'
        # Short streak: retaliate once, but be ready to forgive
        if streak <= 2:
            return 'D'
        # Long defection streak: mostly defect, occasional probe for peace
        if streak >= 4:
            return 'C' if rng.random() < 0.15 else 'D'
        return 'D'

    # Opponent just cooperated
    # If we previously defected, return to cooperation (conciliatory repair)
    if last_me == 'D':
        # If opponent's overall cooperation is high, definitely return to C
        if opp_c >= int(0.6 * n):
            return 'C'
        # Otherwise cooperate to test reformation
        return 'C'

    # Both cooperated last round
    # If opponent has been mostly cooperative, stay cooperative
    if recent_opp_c >= w - 2:
        return 'C'

    # Mixed behavior: reciprocate with slight forgiveness
    if recent_opp_c >= w // 2:
        return 'C'

    # Opponent mostly defecting recently: defect but occasionally probe
    if recent_opp_d >= 6:
        return 'D' if rng.random() > 0.08 else 'C'

    # Default: cooperate to preserve mutual cooperation potential
    return 'C'
